/* ============================ 首页 / 浏览 / 详情 ============================ */
S.browse = { mode: 'series', bsrc: 'all', fmt: 'all', state: 'all', sort: 'updated', view: 'grid', q: '', libFilter: 'all', srcQ: '', srcSub: 'all', sstate: 'all', year: 'all', genre: 'all', region: 'all', scrape: 'all', letter: '', sel: {}, src: 'all', pg: 1, size: 50, pick: false };
const PAGE_SIZES = [20, 50, 100, 200];

function statOf(sid) {
  const s = series(sid) || {};
  if (s.st) return { count: s.st.count, unread: s.st.unread, done: s.st.done, size: 0, total: s.chapters || s.st.count };
  const bs = booksOf(sid), done = bs.filter(b => prog(b.id) && prog(b.id).completed).length;
  const unread = bs.filter(b => !prog(b.id)).length;
  return { count: bs.length || s.dirs || 0, unread, done, size: bs.reduce((a, b) => a + b.size, 0), total: s.chapters || bs.length };
}
function seriesCard(sid) {
  const s = series(sid), st = statOf(sid), p = bestProgress(sid);
  return '<div class="cv" data-series="' + sid + '">' +
    coverArt(s.t, s.t.length > 12 ? s.t.slice(0, 12) + '…' : s.t, {
      id: s.id, kind: 'series',
      fmt: s.online ? 'ONLINE' : (booksOf(sid)[0] || {}).fmt, vert: true,
      badge: s.online ? '<span class="badge gold">' + L.t('在线') + '</span>' : s.status === 'HIATUS' ? '<span class="badge warn">' + L.t('休更') + '</span>' : ''
    }) +
    '<div class="ov"><button class="btn pri sm" data-read="' + sid + '">' + ico('play') + (p ? L.t('继续') : L.t('阅读')) + '</button></div>' +
    '<div class="cv-meta"><div class="t">' + esc(s.t) + '</div><div class="s"><span>' + esc(s.author || '—') + (s.region ? ' · ' + esc(regionCn(s.region)) : '') + '</span><span style="margin-left:auto">' +
    (s.online ? num(s.chapters) + L.t(' 话') : st.count + L.t(' 册')) + '</span></div>' +
    (p ? '<div class="pbar"><i style="width:' + p.pct + '%"></i></div>' : '') + '</div></div>';
}
function bestProgress(sid) {
  const list = booksOf(sid);
  if (!list.length) {
    const s = series(sid);
    if (s && s.st && s.st.count) {
      const pct = Math.round((s.st.done || 0) / s.st.count * 100);
      return pct ? { b: null, p: { pct: pct, at: 0, page: 0, pages: 0 }, pct: pct } : null;
    }
    return null;
  }
  let best = null;
  list.forEach(b => { const p = prog(b.id); if (p && (!best || p.at > best.p.at)) best = { b, p, pct: p.pages ? Math.round(p.page / p.pages * 100) : 0 }; });
  return best;
}
function bookRow(b, pickSel, volIdx, hide) {
  const p = prog(b.id), pct = p && p.pages ? Math.round(p.page / p.pages * 100) : 0;
  const t = bookTitle(b), sub = bookFileSub(b), nb = bookNumCn(b);
  const cell = (pickSel === undefined || pickSel === null) ? ''
    : '<td style="width:36px"><span class="pkbox' + (pickSel ? ' on' : '') + '" style="position:static" data-pick-b="' + b.id + "\" title=\"" + L.t("选择") + "\">" + (pickSel ? '✓' : '') + '</span></td>';
  const volAttr = (volIdx === undefined || volIdx === null) ? '' : ' data-vol="' + volIdx + '"' + (hide ? ' style="display:none"' : '');
  return '<tr class="click" data-book="' + b.id + '"' + volAttr + '>' + cell + '<td style="width:44px">' +
    '<div class="thumb" style="background:' + gradOf(t) + '">' + thumbImg('book', isOnlineBook(b) ? '' : b.id) + '</div></td>' +
    '<td><div style="font-size:13px">' + esc(t) + (nb ? ' <span class="badge">' + nb + '</span>' : '') + '</div>' +
    (sub ? '<div class="mini mono-sm">' + esc(sub) + '</div>' : '') +
    '<div class="mini mono">' + (PROFILE_CN[b.profile] || b.profile) + ' · ' + (b.pages ? num(b.pages) + (((b.profile === 'TXT' || b.profile === 'EPUB') && !b.divina) ? L.t(' 章') : L.t(' 页')) : '—') + ' · ' + bytes(b.size) +
    (b.enc ? ' · ' + b.enc : '') + '</div></td>' +
    '<td>' + statusBadge(b) + '</td>' +
    '<td style="width:150px">' + (p ? '<div class="pbar"><i class="' + (p.completed ? 'done' : '') + '" style="width:' + pct + '%"></i></div><div class="mini mono">' + p.page + '/' + p.pages + ' · ' + deviceCn(p.device) + '</div>' : '<span class="mini">' + L.t('未读') + '</span>') + '</td>' +
    '<td class="num">' + (p ? ago(p.at) : '—') + '</td>' +
    '<td style="width:96px;text-align:right"><button class="btn sm" data-open="' + b.id + '">' + ico('book') + L.t('详情') + '</button></td></tr>';
}
function statusBadge(b) {
  if (b.status === 'ERROR') return '<span class="badge bad">' + L.t('解析失败') + '</span>';
  if (b.status === 'UNSUPPORTED') return '<span class="badge cin">' + L.t('需转换') + '</span>';
  if (isOnlineBook(b) && b.downloaded === false) return '<span class="badge gold">' + L.t('在线代取') + '</span>';
  if (isOnlineBook(b) && b.downloaded) return '<span class="badge moss">' + L.t('已存档 CBZ') + '</span>';
  return '<span class="badge ok">' + L.t('就绪') + '</span>';
}

const HOME_SECTIONS = [
  ['ondeck', L.t('导航 · 下一本')],
  ['published', L.t('最近发布')],
  ['added', L.t('最近添加的书籍')],
  ['recentRead', L.t('最近阅读')],
  ['wantToRead', L.t('待读')],
  ['newSeries', L.t('最近添加的系列')],
  ['updSeries', L.t('最近更新的系列')]
];
const isoAgo = n => new Date(Date.now() - n * 864e5).toISOString().slice(0, 10);

let homeFeed = { ondeck: null, published: null, added: null, recentRead: null, newSeries: null, updSeries: null, busy: false, err: '', at: 0 };
let homeOrder = null;
let homeWant = { rows: null, total: 0, busy: false, err: '', at: 0 };
let homeApp = { data: null, etag: null, busy: false, err: '', at: 0 };

function loadAppHome(silent, onFail) {
  if (!window.LantaiRuntime || !LantaiRuntime.requestEtag) return;
  if (homeApp.busy) return;
  if (!silent && homeApp.data && Date.now() - homeApp.at < 5000) return;
  homeApp.busy = true;
  LantaiRuntime.requestEtag('api/lantai/v1/app/home?limit=16', homeApp.etag).then(res => {
    if (res && res.data) {
      homeApp.data = res.data;
      homeApp.etag = res.etag || null;
      homeApp.err = '';
      homeApp.at = Date.now();
    } else if (res && res.notModified) {
      homeApp.at = Date.now();
    }
  }).catch(e => {
    homeApp.err = String(e && e.message ? e.message : e);
    if (onFail) onFail();
  }).then(() => {
    homeApp.busy = false;
    if (!silent && S.route === '/home' && homeApp.data) render();
  });
}

function appBookCardHtml(c) {
  const seed = (c.seriesTitle || c.title || '') + c.id;
  return '<div class="cv" data-book="' + c.id + '">' +
    coverArt(seed, c.seriesTitle || c.title, { id: c.id, kind: 'book', fmt: c.profile }) +
    '<div class="cv-meta"><div class="t">' + esc(c.title) + '</div>' +
    '<div class="s"><span>' + esc(c.seriesTitle || '') + (c.number ? ' · ' + esc(c.number) : '') + '</span></div></div></div>';
}
function appSeriesCardHtml(c) {
  const pct = c.books ? Math.round((c.read || 0) / c.books * 100) : 0;
  const t = c.title || '';
  return '<div class="cv" data-series="' + c.id + '">' +
    coverArt(t, t.length > 12 ? t.slice(0, 12) + '…' : t, { id: c.id, kind: 'series', vert: true }) +
    '<div class="cv-meta"><div class="t">' + esc(t) + '</div>' +
    '<div class="s"><span>' + (c.read || 0) + '/' + (c.books || 0) + L.t(' 册') + '</span><span style="margin-left:auto">' + esc(shortAgo(c.at)) + '</span></div>' +
    (c.read ? '<div class="pbar"><i style="width:' + pct + '%"></i></div>' : '') + '</div></div>';
}
function continueCardHtml(c) {
  const pct = c.pages ? Math.round((c.page || 0) / c.pages * 100) : 0;
  const unit = L.t(c.profile === 'DIVINA' || c.profile === 'PDF' ? 'home.unit.page' : 'home.unit.chapter');
  return '<div class="cv" data-book="' + c.id + '">' +
    coverArt((c.seriesTitle || c.title) + c.id, c.seriesTitle || c.title, { id: c.id, kind: 'book', fmt: c.profile, badge: c.completed ? '<span class="badge ok">' + esc(L.t('home.readBadge')) + '</span>' : '' }) +
    '<div class="ov"><button class="btn pri sm" data-readbook="' + c.id + '">' + ico('book') + esc(L.t('home.cont.page', { n: c.page || 0, u: unit })) + '</button></div>' +
    '<div class="cv-meta"><div class="t">' + esc(c.seriesTitle || c.title) + '</div>' +
    '<div class="s"><span class="mono">' + (c.page || 0) + '/' + (c.pages || 0) + '</span><span style="margin-left:auto">' + esc(shortAgo(c.at)) + '</span></div>' +
    '<div class="pbar"><i style="width:' + pct + '%"></i></div></div></div>';
}
function shortAgo(v) {
  if (!v) return '';
  const t = new Date(v).getTime();
  if (isNaN(t)) return '';
  const d = Math.floor((Date.now() - t) / 864e5);
  if (d <= 0) return L.t('ago.today');
  if (d === 1) return L.t('ago.yesterday');
  if (d < 30) return L.t('ago.days', { n: d });
  return String(v).slice(0, 10);
}
function appShelf(title, hint, cards, kind, key, empty) {
  const list = (cards || []).slice(0, 16);
  const head = '<div class="card-h"><h3>' + esc(title) + '</h3><span class="hint">' + esc(hint) + '</span></div>';
  if (!list.length) {
    return '<div class="card" style="margin-bottom:18px">' + head +
      '<div class="mini" style="padding:6px 0 16px">' + esc(empty || L.t(kind === 'series' ? 'shelf.emptySeries' : 'shelf.emptyBook')) + '</div></div>';
  }
  const body = kind === 'series' ? list.map(appSeriesCardHtml).join('') : list.map(appBookCardHtml).join('');
  return '<div class="card" style="margin-bottom:18px">' + head +
    '<div class="shelf" data-shelf="' + esc(key || title) + '" style="--cw:140px">' + body + '</div>' +
    '<div class="rowflex" style="justify-content:center;padding:2px 0 12px"><button class="btn sm ghost" data-shelf-more="' + esc(key || title) + '" style="display:none">' + esc(L.t('shelf.moreShort')) + '</button></div></div>';
}

const pagedIds = p => unwrapPage(p).map(x => x.id);

function loadHomeFeed() {
  if (homeFeed.busy || !window.LantaiRuntime) return;
  if (homeFeed.at && Date.now() - homeFeed.at < 30000) return;
  homeFeed.busy = true;
  const P = LantaiRuntime.request;
  Promise.all([
    P('api/v1/books/ondeck?size=24&readerView=true').catch(() => null),
    P('api/v1/books/latest?size=24&readerView=true').catch(() => null),
    P('api/v1/books/list?size=24&readerView=true', { method: 'POST', body: { condition: { releaseDate: { operator: 'isNotNull' } } } }).catch(() => null),
    P('api/v1/books/list?size=24&readerView=true', { method: 'POST', body: { condition: { anyOf: [{ readStatus: { operator: 'is', value: 'IN_PROGRESS' } }, { readStatus: { operator: 'is', value: 'READ' } }] } } }).catch(() => null),
    P('api/v1/series/new?size=24').catch(() => null),
    P('api/v1/series/updated?size=24').catch(() => null)
  ]).then(out => {
    const got = out.filter(Boolean).length;
    if (got) {
      if (out[0]) homeFeed.ondeck = pagedIds(out[0]);
      if (out[1]) homeFeed.added = pagedIds(out[1]);
      if (out[2]) homeFeed.published = pagedIds(out[2]);
      if (out[3]) homeFeed.recentRead = pagedIds(out[3]);
      if (out[4]) homeFeed.newSeries = pagedIds(out[4]);
      if (out[5]) homeFeed.updSeries = pagedIds(out[5]);
    }
    homeFeed.err = got ? '' : L.t('首页分组数据加载失败');
    homeFeed.at = Date.now();
    if (got && S.route === '/home' && !homeApp.data) render();
  }).catch(() => {
    homeFeed.err = L.t('首页分组数据加载失败');
    homeFeed.at = Date.now();
  }).then(() => { homeFeed.busy = false; });
}

function loadHomeWant() {
  if (homeWant.busy || !window.LantaiRuntime || !LantaiRuntime.wantToReadPage) return;
  if (homeWant.at && Date.now() - homeWant.at < 30000) return;
  homeWant.busy = true;
  LantaiRuntime.wantToReadPage(0, 16).then(r => {
    homeWant.rows = (r && r.rows) || [];
    homeWant.total = (r && r.total) || 0;
    homeWant.err = '';
    homeWant.at = Date.now();
    if (S.route === '/home') render();
  }).catch(e => {
    homeWant.err = String(e && e.message ? e.message : e);
    homeWant.at = Date.now();
  }).then(() => { homeWant.busy = false; });
}

function loadHomeOrder() {
  if (homeOrder !== null || !window.LantaiRuntime) return;
  homeOrder = HOME_SECTIONS.map(x => x[0]);
  LantaiRuntime.request('api/v1/client-settings/user/list').then(list => {
    const raw = list && list['lantai.webui.home'];
    if (raw && raw.value) {
      const arr = JSON.parse(raw.value);
      if (Array.isArray(arr) && arr.length) {
        const kept = arr.filter(k => HOME_SECTIONS.some(s => s[0] === k));
        HOME_SECTIONS.forEach(s => { if (kept.indexOf(s[0]) < 0) kept.push(s[0]); });
        homeOrder = kept;
      }
    }
  }).catch(() => { }).then(() => { if (S.route === '/home') render(); });
}

function saveHomeOrder() {
  if (!window.LantaiRuntime) return;
  LantaiRuntime.request('api/v1/client-settings/user', { method: 'PATCH', body: { 'lantai.webui.home': { value: JSON.stringify(homeOrder) } } })
    .then(() => toast(L.t('首页分组已保存'), 'ok'))
    .catch(e => toast(L.t('保存失败：') + onlineErrText(e), 'err'));
}

function shiftList(arr, k, d) {
  const i = arr.indexOf(k), j = i + d;
  if (i < 0 || j < 0 || j >= arr.length) return arr;
  const out = arr.slice();
  out.splice(i, 1);
  out.splice(j, 0, k);
  return out;
}

function homeSectionModal() {
  let order = (homeOrder || HOME_SECTIONS.map(x => x[0])).slice();
  const on = new Set(order);
  const row = k => {
    const meta = HOME_SECTIONS.find(s => s[0] === k);
    return '<div style="display:flex;align-items:center;gap:9px;padding:9px 0;border-bottom:1px solid var(--line)">' +
      '<input type="checkbox" data-hsec="' + k + '"' + (on.has(k) ? ' checked' : '') + ' style="width:15px;height:15px;margin:0;accent-color:var(--acc)">' +
      '<span style="flex:1;font-size:13px">' + meta[1] + '</span>' +
      '<button class="btn xs" data-hup="' + k + '">↑</button><button class="btn xs" data-hdn="' + k + '">↓</button></div>';
  };
  const show = () => openModal({
    title: L.t('首页分组'), width: 470,
    body: '<div class="note">' + L.t('勾选要显示的分组，用箭头调整顺序。') + '</div>' + order.map(row).join(''),
    foot: '<button class="btn" data-x>' + L.t('取消') + '</button><button class="btn pri" data-ok>' + L.t('保存') + '</button>',
    after() {
      $('#modal [data-x]').onclick = closeModal;
      $$('#modal [data-hsec]').forEach(el => el.onchange = () => { if (el.checked) on.add(el.dataset.hsec); else on.delete(el.dataset.hsec); });
      $$('#modal [data-hup]').forEach(el => el.onclick = () => { order = shiftList(order, el.dataset.hup, -1); show(); });
      $$('#modal [data-hdn]').forEach(el => el.onclick = () => { order = shiftList(order, el.dataset.hdn, 1); show(); });
      $('#modal [data-ok]').onclick = () => {
        homeOrder = order.filter(k => on.has(k));
        closeModal();
        saveHomeOrder();
        render();
      };
    }
  });
  show();
}

function homeBookShelf(title, hint, ids, key, empty) {
  const list = (ids || []).map(x => (typeof x === 'string' ? book(x) : x)).filter(Boolean).slice(0, 16);
  const head = '<div class="card-h"><h3>' + esc(title) + '</h3><span class="hint">' + esc(hint) + '</span></div>';
  if (!list.length) {
    return '<div class="card" style="margin-bottom:18px">' + head +
      '<div class="mini" style="padding:6px 0 16px">' + esc(empty || L.t('shelf.emptyBook')) + '</div></div>';
  }
  return '<div class="card" style="margin-bottom:18px">' + head +
    '<div class="shelf" data-shelf="' + esc(key || title) + '" style="--cw:140px">' + list.map(b => {
      const s = series(b.s) || { t: b.name, id: '' };
      return '<div class="cv" data-book="' + b.id + '">' + coverArt(s.t + b.id, s.t, { id: isOnlineBook(b) ? '' : b.id, kind: 'book', fmt: b.fmt }) +
        '<div class="cv-meta"><div class="t">' + esc(b.name) + '</div><div class="s"><span>' + esc(s.t) + '</span></div></div></div>';
    }).join('') + '</div>' +
    '<div class="rowflex" style="justify-content:center;padding:2px 0 12px"><button class="btn sm ghost" data-shelf-more="' + esc(key || title) + '" style="display:none">' + esc(L.t('shelf.moreShort')) + '</button></div></div>';
}

function homeSeriesShelf(title, hint, ids, key, empty) {
  const list = (ids || []).map(series).filter(Boolean).slice(0, 16);
  const head = '<div class="card-h"><h3>' + esc(title) + '</h3><span class="hint">' + esc(hint) + '</span></div>';
  if (!list.length) {
    return '<div class="card" style="margin-bottom:18px">' + head +
      '<div class="mini" style="padding:6px 0 16px">' + esc(empty || L.t('shelf.emptySeries')) + '</div></div>';
  }
  return '<div class="card" style="margin-bottom:18px">' + head +
    '<div class="shelf" data-shelf="' + esc(key || title) + '" style="--cw:140px">' + list.map(s => seriesCard(s.id)).join('') + '</div>' +
    '<div class="rowflex" style="justify-content:center;padding:2px 0 12px"><button class="btn sm ghost" data-shelf-more="' + esc(key || title) + '" style="display:none">' + esc(L.t('shelf.moreShort')) + '</button></div></div>';
}

let shelfRows = {};
function shelfCols(box) {
  const raw = String((window.getComputedStyle ? getComputedStyle(box).gridTemplateColumns : '') || '').trim();
  const tpl = raw.split(/\s+/).filter(x => x && x !== 'none');
  if (tpl.length) return tpl.length;
  const view = document.getElementById('view');
  const w = view ? view.clientWidth : 0;
  return w > 240 ? Math.max(2, Math.floor((w - 72) / 154)) : 2;
}
function clipShelf(box, host) {
  const key = box.dataset.shelf;
  const cards = Array.prototype.filter.call(box.children, c => c.classList.contains('cv'));
  const btn = host.querySelector('[data-shelf-more="' + key + '"]');
  if (!cards.length) { if (btn) btn.style.display = 'none'; return; }
  const cols = shelfCols(box);
  const rows = Math.max(1, Number(shelfRows[key]) || 1);
  const limit = cols * rows;
  const more = cards.length > limit;
  cards.forEach((c, i) => { c.style.display = i < limit ? '' : 'none'; });
  if (!btn) return;
  if (!more && rows <= 1) { btn.style.display = 'none'; return; }
  btn.style.display = '';
  btn.textContent = more ? L.t('shelf.more', { n: cards.length - limit }) : L.t('shelf.collapse');
  btn.onclick = () => {
    shelfRows[key] = more ? rows + 1 : 1;
    clipShelves(host);
  };
}
function clipShelves(root) {
  const host = root || document;
  host.querySelectorAll('[data-shelf]').forEach(box => clipShelf(box, host));
}
let shelfTimer = 0;
window.addEventListener('resize', () => {
  clearTimeout(shelfTimer);
  shelfTimer = setTimeout(() => { if (document.querySelector('[data-shelf]')) clipShelves(document); }, 160);
});

function homeSectionsHtml() {
  const A = homeApp.data;
  if (A) {
    const order = homeOrder || HOME_SECTIONS.map(x => x[0]);
    const map = {
      ondeck: () => appShelf(L.t('sec.ondeck.title'), L.t('sec.ondeck.hint'), A.continueReading, 'book', 'ondeck', L.t('sec.ondeck.empty')),
      published: () => appShelf(L.t('sec.published.title'), L.t('sec.published.hint'), A.published, 'book', 'published', L.t('sec.published.empty')),
      added: () => appShelf(L.t('sec.added.title'), L.t('sec.added.hint'), A.added, 'book', 'added'),
      recentRead: () => appShelf(L.t('sec.recentRead.title'), L.t('sec.recentRead.hint'), A.recentRead, 'book', 'recentRead', L.t('sec.recentRead.empty')),
      wantToRead: () => homeBookShelf(L.t('待读'), L.t('准备读的书'), homeWant.rows, 'wantToRead', L.t('还没有待读的书，在书籍或系列详情里添加。')),
      newSeries: () => appShelf(L.t('sec.newSeries.title'), L.t('sec.added.hint'), A.newSeries, 'series', 'newSeries'),
      updSeries: () => appShelf(L.t('sec.updSeries.title'), L.t('sec.updSeries.hint'), A.updatedSeries, 'series', 'updSeries')
    };
    return order.map(k => (map[k] ? map[k]() : '')).join('');
  }
  const F = homeFeed;
  const order = homeOrder || HOME_SECTIONS.map(x => x[0]);
  const pubSorted = (F.published || []).map(book).filter(b => b && b.pub).sort((a, b) => b.pub.localeCompare(a.pub));
  const pubRecent = pubSorted.filter(b => b.pub >= isoAgo(30));
  const pubIds = (pubRecent.length ? pubRecent : pubSorted).slice(0, 12).map(b => b.id);
  const readIds = (F.recentRead || []).map(book).filter(Boolean)
    .sort((a, b) => ((prog(b.id) || {}).at || 0) - ((prog(a.id) || {}).at || 0)).slice(0, 12).map(b => b.id);
  const map = {
    ondeck: () => homeBookShelf(L.t('sec.ondeck.title'), L.t('sec.ondeck.hint'), F.ondeck, 'ondeck', L.t('sec.ondeck.empty')),
    published: () => homeBookShelf(L.t('sec.published.title'), L.t('sec.published.hint30'), pubIds, 'published', L.t('sec.published.empty')),
    added: () => homeBookShelf(L.t('sec.added.title'), L.t('sec.added.hint'), F.added, 'added'),
    recentRead: () => homeBookShelf(L.t('sec.recentRead.title'), L.t('sec.recentRead.hint'), readIds, 'recentRead', L.t('sec.recentRead.empty')),
    wantToRead: () => homeBookShelf(L.t('待读'), L.t('准备读的书'), homeWant.rows, 'wantToRead', L.t('还没有待读的书，在书籍或系列详情里添加。')),
    newSeries: () => homeSeriesShelf(L.t('sec.newSeries.title'), L.t('sec.added.hint'), F.newSeries, 'newSeries'),
    updSeries: () => homeSeriesShelf(L.t('sec.updSeries.title'), L.t('sec.updSeries.hint'), F.updSeries, 'updSeries')
  };
  return order.map(k => (map[k] ? map[k]() : '')).join('');
}

