  const reading = BOOKS.filter(b => prog(b.id) && !prog(b.id).completed).sort((a, b) => prog(b.id).at - prog(a.id).at).slice(0, 6);
  const fedReading = A && A.continueReading && A.continueReading.length ? A.continueReading.slice(0, 6) : null;
