let etTimer = null, etSeq = 0;
function etStop() {
  if (etTimer) { clearTimeout(etTimer); etTimer = null; }
  etSeq++;
}
function etView(html, foot) {
  const b = $('#mBody');
  if (!b) return;
  b.innerHTML = html;
  if (foot != null) {
    $('#mFoot').innerHTML = foot;
    const x = $('#modal [data-x]');
    if (x) x.onclick = closeModal;
  }
}
function etWaitHtml(label, sec, extra) {
  return '<div class="rowflex" style="gap:12px;align-items:center"><div class="spinner"></div><div>' +
    '<div style="font-size:13px">' + esc(label) + '</div>' +
    '<div class="mini">' + L.t('已等待 ') + sec + L.t(' 秒') + (extra ? ' · ' + esc(extra) : '') + '</div></div></div>';
}
function etRefresh() {
  trashData = null; trashErr = '';
  LantaiRuntime.hydrate(true).catch(() => {}).then(() => {
    if (S.route === '/trash') loadTrash();
    if (String(S.route).indexOf('/settings') === 0) loadLibStats(true);
    render();
  });
}
function etWatch(id) {
  const seq = etSeq, started = Date.now();
  let seen = false, ticks = 0;
  const sec = () => Math.round((Date.now() - started) / 1000);
  const done = timeout => {
    etStop();
    etRefresh();
    etView('<div class="note ' + (timeout ? 'gold' : '') + '">' + ico('trash') + ' ' + (timeout ? L.t('任务仍在后台进行') : L.t('清空任务已结束')) + '</div>' +
      '<div class="mini" style="margin-top:10px">' + (timeout ? L.t('可先关闭本窗口，稍后到任务页查看进度。') : L.t('回收站与书库数据已刷新。若条目仍在，可在任务页「已完成」里查看失败原因。')) + '</div>',
      '<button class="btn" data-x>' + L.t('关闭') + '</button>');
    if (!timeout) toast(L.t('清空任务已结束'), 'ok');
  };
  const step = () => {
    if (seq !== etSeq) return;
    ticks++;
    LantaiRuntime.request('api/lantai/v1/tasks?type=EmptyTrash&size=500')
      .then(d => {
        if (seq !== etSeq) return;
        const t = ((d && d.tasks) || []).filter(x => x.libraryId === id).pop();
        if (t) {
          seen = true;
          etView(etWaitHtml(t.owner ? L.t('正在清空回收站…') : L.t('排队中，等待后台任务…'), sec(),
            num(d.running || 0) + L.t(' 进行 / ') + num(d.queued || 0) + L.t(' 排队')), '<button class="btn" data-x>' + L.t('后台进行') + '</button>');
        } else if (seen || ticks >= 2) {
          return done(false);
        }
        if (sec() > 600) return done(true);
        etTimer = setTimeout(step, 1200);
      })
      .catch(() => {
        if (seq !== etSeq) return;
        if (ticks >= 5) {
          etStop();
          etView('<div class="note red">' + ico('alert') + L.t(' 读取任务状态失败，清空仍在后台进行') + '</div>' +
            '<div class="mini" style="margin-top:10px">' + L.t('可到任务页查看进度。') + '</div>', '<button class="btn" data-x>' + L.t('关闭') + '</button>');
          return;
        }
        etTimer = setTimeout(step, 2000);
      });
  };
  step();
}
function emptyLibTrash(id) {
  const l = lib(id);
  etStop();
  openModal({
    title: L.t('清空库回收站'), width: 460,
    body: '<div class="note red">' + L.t('清空「') + esc(l ? l.name : id) + L.t('」的回收站目录，其中的文件会被彻底删除，不可恢复。') + '</div>' +
      '<div class="field" style="margin-top:10px"><label>' + L.t('输入「清空」确认') + '</label><input class="inp" id="etIn" autocomplete="off"></div>',
    foot: '<button class="btn" data-x>' + L.t('取消') + '</button><button class="btn danger" data-ok>' + L.t('确认清空') + '</button>',
    onClose: etStop,
    after() {
      $('#modal [data-x]').onclick = closeModal;
      $('#modal [data-ok]').onclick = () => {
        if ($('#etIn').value.trim() !== L.t('清空')) return toast(L.t('确认词不对'), 'err');
        const ok = $('#modal [data-ok]');
        ok.disabled = true;
        ok.textContent = L.t('提交中…');
        LantaiRuntime.request('api/v1/libraries/' + id + '/empty-trash', { method: 'POST' })
          .then(() => { etSeq++; etWatch(id); })
          .catch(e => {
            ok.disabled = false;
            ok.textContent = L.t('确认清空');
            toast(L.t('提交失败：') + onlineErrText(e), 'err');
          });
      };
    }
  });
}

