function bulkReparse(ids) {
  openModal({
    title: L.t('重新解析'), width: 480,
    body: '<div class="note">' + L.t('对 ') + '<b>' + ids.length + '</b>' + L.t(' 个系列重新读取文件内元数据与封面，并重新分析文件结构。已在解析中的书会跳过。') + '</div>' +
      '<div class="note gold" style="margin-top:10px">' + L.t('任务在后台排队执行，系列较多时需要几分钟。') + '</div>',
    foot: '<button class="btn" data-x>' + L.t('取消') + '</button><button class="btn pri" data-ok>' + L.t('开始解析') + '</button>',
    after() {
      $('#modal [data-x]').onclick = closeModal;
      $('#modal [data-ok]').onclick = () => {
        closeModal();
        let i = 0, ok = 0, bad = 0;
        const step = () => {
          if (i >= ids.length) {
            bulkProg('');
            toast(L.t('已提交 ') + ok + ' / ' + ids.length + L.t(' 个系列') + (bad ? L.t('，失败 ') + bad : ''), bad ? 'warn' : 'ok', 3600);
            return;
          }
          const id = ids[i++];
          bulkProg(L.t('解析 ') + i + ' / ' + ids.length);
          Promise.all([
            LantaiRuntime.request('api/v1/series/' + id + '/metadata/refresh', { method: 'POST' }).then(() => true).catch(() => false),
            LantaiRuntime.request('api/v1/series/' + id + '/analyze', { method: 'POST' }).then(() => true).catch(() => false)
          ]).then(res => { if (res[0] && res[1]) ok++; else bad++; setTimeout(step, 80); });
        };
        step();
      };
    }
  });
}

function bulkScrape(ids, run, bookIds) {
  const byBook = Array.isArray(bookIds) && bookIds.length > 0;
  const label = run ? L.t('重新刮削') : L.t('加入刮削名单');
  const scope = byBook
    ? L.t('已选 ') + '<b>' + bookIds.length + '</b>' + L.t(' 本书，分属 ') + '<b>' + ids.length + '</b>' + L.t(' 个系列')
    : '<b>' + ids.length + '</b>' + L.t(' 个系列');
  openModal({
    title: label, width: 480,
    body: '<div class="note">' + scope + (run ? L.t(' 加入刮削名单并立即开始刮削。') : L.t(' 加入刮削名单，稍后在刮削页统一开始刮削。')) + '</div>' +
      (byBook ? '<div class="note" style="margin-top:10px">' + L.t('只登记选中的 ') + bookIds.length + L.t(' 册：检索仍按系列进行，但写入只落在选中的册上，同系列其余册不受影响。') + '</div>' : '') +
      '<div class="note gold" style="margin-top:10px">' + (run ? L.t('会消耗元数据源配额，已存在的名单项会被跳过。') : L.t('只登记不请求，开始刮削时才消耗配额。')) + '</div>',
    foot: '<button class="btn" data-x>' + L.t('取消') + '</button><button class="btn pri" data-ok>' + (run ? L.t('开始刮削') : L.t('加入名单')) + '</button>',
    after() {
      $('#modal [data-x]').onclick = closeModal;
      $('#modal [data-ok]').onclick = () => {
        const btn = $('#modal [data-ok]');
        btn.disabled = true;
        LantaiRuntime.request('api/lantai/v1/scrape/queue', { method: 'POST', body: byBook ? { bookIds: bookIds, run: run } : { seriesIds: ids, run: run } })
          .then(r => {
            closeModal();
            toast(L.t('已登记 ') + r.added + L.t(' 个系列') + (byBook ? L.t('、') + bookIds.length + L.t(' 册') : '') +
              (r.skipped ? L.t('，跳过 ') + r.skipped + L.t(' 个已在名单') : '') +
              (r.notReady ? L.t('，') + r.notReady + L.t(' 个未解析完成已跳过') : '') + (run ? L.t('，正在刮削…') : ''), 'ok', 3600);
            S.browse.sel = {};
            render();
            loadScrape();
          })
          .catch(e => { btn.disabled = false; toast(L.t('提交失败：') + onlineErrText(e), 'err'); });
      };
    }
  });
}

function bulkExclude(ids) {
  const onlineCount = ids.filter(id => series(id) && series(id).online).length;
  const localCount = ids.length - onlineCount;
  openModal({
    title: L.t('移出书库'), width: 500,
    body: '<div class="note">' + L.t('把 ') + '<b>' + ids.length + '</b>' + L.t(' 个系列移出书库：本地 ') + localCount + L.t(' 个、在线书架 ') + onlineCount + L.t(' 个。移出后可在回收站找回。') + '</div>' +
      '<label class="sw" style="margin-top:14px"><input type="checkbox" id="bxDel"><i></i><span>' + L.t('同时删除文件（本地移入回收站，在线清除已存档 CBZ）') + '</span></label>' +
      '<div class="note red" style="margin-top:12px">' + L.t('不勾选时只从书库移除，磁盘文件原样保留。') + '</div>',
    foot: '<button class="btn" data-x>' + L.t('取消') + '</button><button class="btn danger" data-ok>' + L.t('确认移出') + '</button>',
    after() {
      $('#modal [data-x]').onclick = closeModal;
      $('#modal [data-ok]').onclick = () => {
        const del = $('#bxDel') && $('#bxDel').checked;
        const btn = $('#modal [data-ok]');
        btn.disabled = true;
        let ok = 0;
        const step = (i) => {
          if (i >= ids.length) {
            closeModal();
            toast(L.t('已移出 ') + ok + ' / ' + ids.length + L.t(' 个系列'), ok === ids.length ? 'ok' : 'warn', 3600);
            S.browse.sel = {};
            return LantaiRuntime.hydrate().then(() => render());
          }
          const id = ids[i];
          const s = series(id);
          bulkProg(L.t('移出 ') + (i + 1) + ' / ' + ids.length);
          if (s && s.online) {
            LantaiRuntime.request('api/lantai/v1/online/series/' + id + '?purgeDownloads=' + (del ? 'true' : 'false'), { method: 'DELETE' })
              .then(() => { ok++; }).catch(() => null).then(() => setTimeout(() => step(i + 1), 120));
            return;
          }
          const delReq = del ? LantaiRuntime.request('api/v1/series/' + id + '/file', { method: 'DELETE' }).catch(() => null) : Promise.resolve();
          delReq
            .then(() => LantaiRuntime.request('api/lantai/v1/trash/excluded/' + id, { method: 'PUT' }))
            .then(() => { ok++; })
            .catch(() => null)
            .then(() => setTimeout(() => step(i + 1), 120));
        };
        step(0);
      };
    }
  });
}

function pickTarget(kind, ids) {
  if (!ids.length) return toast(L.t('没有可加入的条目'), 'err');
  const path = kind === 'coll' ? 'api/v1/collections' : 'api/v1/readlists';
  const label = kind === 'coll' ? L.t('合集') : L.t('阅读清单');
  LantaiRuntime.request(path + '?unpaged=true').then(p => {
    const list = unwrapPage(p);
    openModal({
      title: L.t('加入') + label, width: 480,
      body: list.length ? list.map(x => '<div class="list-i"><span class="gi">' + ico(kind === 'coll' ? 'collection' : 'readlist') + '</span>' +
        '<div style="flex:1;min-width:0"><div class="gt">' + esc(x.name) + '</div><div class="gs mini">' + L.t('现有 ') + ((kind === 'coll' ? x.seriesIds : x.bookIds) || []).length + L.t(' 项') + '</div></div>' +
        '<button class="btn xs" data-pick="' + x.id + "\">" + L.t("加入") + '</button></div>').join('')
        : '<div class="mini">' + L.t('还没有') + label + L.t('，先到') + label + L.t('页新建一个。') + '</div>' +
        '<div class="note" style="margin-top:10px">' + L.t('本次将加入 ') + ids.length + L.t(' 项。') + '</div>',
      foot: '<button class="btn" data-x>' + L.t('关闭') + '</button>',
      after() {
        $('#modal [data-x]').onclick = closeModal;
        $$('#modal [data-pick]').forEach(el => el.onclick = () => {
          const target = list.find(x => x.id === el.dataset.pick);
          const cur = (kind === 'coll' ? target.seriesIds : target.bookIds) || [];
          const next = Array.from(new Set(cur.concat(ids)));
          const body = kind === 'coll' ? { seriesIds: next } : { bookIds: next };
          LantaiRuntime.request(path + '/' + target.id, { method: 'PATCH', body: body })
            .then(() => { closeModal(); toast(L.t('已加入，共 ') + next.length + L.t(' 项'), 'ok'); S.browse.sel = {}; render(); })
            .catch(e => toast(L.t('加入失败：') + onlineErrText(e), 'err'));
        });
      }
    });
  }).catch(e => toast(L.t('读取失败：') + onlineErrText(e), 'err'));
}

