function pgNums(cur, pages) {
  if (pages <= 9) return Array.from({ length: pages }, (_, i) => i + 1);
  const out = [];
  for (let i = 1; i <= pages; i++) {
    if (i === 1 || i === pages || Math.abs(i - cur) <= 2) out.push(i);
    else if (out[out.length - 1] !== '…') out.push('…');
  }
  return out;
}
function pagerBarHtml(o) {
  const total = Math.max(0, Number(o.total) || 0);
  if (total <= 0) return '';
  const sizes = o.sizes || PAGE_SIZES;
  const all = Number(o.size) === 0;
  const per = all ? Math.max(1, total) : (Number(o.size) || sizes[0] || 20);
  const pages = Math.max(1, Math.ceil(total / per));
  const cur = clamp(Number(o.page) || 1, 1, pages);
  const nums = all ? [] : pgNums(cur, pages);
  const known = sizes.indexOf(Number(o.size)) >= 0;
  const custom = all || known ? '' : Number(o.size);
  const unit = o.unit || L.t(' 条');
  return '<div class="pager-gap"></div><div class="pager-dock"><div class="pager-in" data-pages="' + pages + '">' +
    '<span class="pg-lbl">' + L.t('pg.size') + '</span><div class="chips">' +
    sizes.map(n => '<span class="chip' + (!all && Number(o.size) === n ? ' on' : '') + '" data-pgsize="' + n + '">' + n + '</span>').join('') +
    (o.allowAll === false ? '' : '<span class="chip' + (all ? ' on' : '') + '" data-pgsize="0">' + L.t('pg.all') + '</span>') +
    '<input class="inp" style="width:70px;text-align:center" type="number" min="1" max="' + (o.maxSize || 2000) + '" placeholder="' + L.t('pg.custom') + '" value="' + custom + '" data-pgsize-in>' +
    '</div>' +
    '<span class="pg-sep"></span>' +
    (all
      ? '<span class="pg-info">' + L.t('pg.total', { n: num(total), u: unit }) + '</span>'
      : '<button class="btn sm" data-pg="' + (cur - 1) + '"' + (cur <= 1 ? ' disabled' : '') + '>' + L.t('page.prev') + '</button>' +
        nums.map(n => n === '…' ? '<span class="pg-lbl">…</span>'
          : '<button class="btn sm' + (n === cur ? ' pri' : ' ghost') + '" data-pg="' + n + '">' + n + '</button>').join('') +
        '<button class="btn sm" data-pg="' + (cur + 1) + '"' + (cur >= pages ? ' disabled' : '') + '>' + L.t('page.next') + '</button>' +
        '<span class="pg-sep"></span><span class="pg-lbl">' + L.t('pg.jump') + '</span>' +
        '<input class="inp" style="width:58px;text-align:center" type="number" min="1" max="' + pages + '" value="' + cur + '" data-pgjump>' +
        '<span class="pg-info">/ ' + pages + ' ' + L.t('unit.page') + ' · ' + L.t('pg.total', { n: num(total), u: unit }) + '</span>') +
    '</div></div>';
}
function wirePagerBar(root, h) {
  const box = root.querySelector('.pager-in');
  if (!box) return;
  const pages = Math.max(1, Number(box.getAttribute('data-pages')) || 1);
  const maxSize = h.maxSize || 2000;
  const top = () => { const v = $('#view'); if (v) v.scrollTop = 0; };
  box.querySelectorAll('[data-pg]').forEach(el => el.onclick = () => {
    h.onPage(clamp(Number(el.dataset.pg) || 1, 1, pages));
    top();
  });
  box.querySelectorAll('[data-pgsize]').forEach(el => el.onclick = () => {
    h.onSize(Number(el.dataset.pgsize));
    top();
  });
  const si = box.querySelector('[data-pgsize-in]');
  if (si) si.onchange = () => {
    const n = clamp(Number(si.value) || maxSize, 1, maxSize);
    si.value = n;
    h.onSize(n);
    top();
  };
  const ji = box.querySelector('[data-pgjump]');
  if (ji) ji.onchange = () => {
    h.onPage(clamp(Number(ji.value) || 1, 1, pages));
    top();
  };
}
function pagerHtml(B, total) {
  return pagerBarHtml({
    page: B.pg,
    size: B.size,
    total: total,
    unit: ' ' + L.t(B.mode === 'books' ? 'unit.book' : 'unit.series'),
    maxSize: 2000
  });
}
function wirePager(v, B) {
  wirePagerBar(v, {
    maxSize: 2000,
    onPage: p => { B.pg = p; render(); },
    onSize: s => {
      if (s === 0) {
        askConfirm(L.t('ask.loadAll'), L.t('将一次性加载全部条目到浏览器，可能占用数百 MB 内存。确定继续？'), () => {
          B.size = 0;
          B.pg = 1;
          render();
        });
        return;
      }
      B.size = s;
      B.pg = 1;
      render();
    }
  });
}
function modeBarHtml(B) {
  const inLib = !!currentLibId();
  const onlineOn = onlineContentReady();
  if (!onlineOn && B.bsrc === 'online') B.bsrc = 'all';
  return '<div class="frow"><span class="lbl" style="margin:0">' + L.t('显示') + '</span><div class="chips">' +
    '<span class="chip' + (B.mode === 'books' ? '' : ' on') + "\" data-bmode=\"series\">" + L.t("按系列") + '</span>' +
    '<span class="chip' + (B.mode === 'books' ? ' on' : '') + "\" data-bmode=\"books\">" + L.t("全部书籍") + '</span></div>' +
    (inLib ? '' : '<span class="sep"></span><span class="lbl" style="margin:0">' + L.t('来源') + '</span><div class="chips">' +
      [['all', L.t('全部')], ['local', L.t('本地')]].concat(onlineOn ? [['online', L.t('在线')]] : []).map(x => '<span class="chip' + ((B.bsrc || 'all') === x[0] ? ' on' : '') + '" data-bsrc="' + x[0] + '">' + x[1] + '</span>').join('') + '</div>') +
    '</div>';
}
function wireModeChips(v) {
  v.querySelectorAll('[data-bmode]').forEach(el => el.onclick = () => {
    if (S.browse.mode === el.dataset.bmode) return;
    S.browse.mode = el.dataset.bmode;
    S.browse.pg = 1;
    S.browse.letter = '';
    S.browse.sel = {};
    render();
    $('#view').scrollTop = 0;
  });
  v.querySelectorAll('[data-bsrc]').forEach(el => el.onclick = () => {
    S.browse.bsrc = el.dataset.bsrc;
    S.browse.pg = 1;
    render();
    $('#view').scrollTop = 0;
  });
}
const bookTitle = b => (b.mdTitle && String(b.mdTitle).trim()) ? String(b.mdTitle).trim() : b.name;
const bookFileSub = b => bookTitle(b) === b.name ? '' : b.name;
const bookNumCn = b => { const n = String(b.mdNum || '').trim(); return n ? L.t('第 ') + n + L.t(' 册') : ''; };
function fchip(attr, key, val, label, B) {
  return '<span class="chip' + ((B[key] || 'all') === val ? ' on' : '') + '" data-' + attr + '="' + esc(val) + '">' + esc(label) + '</span>';
}
function libLetterBarHtml(B, mode) {
  const raw = groupCache.list || [];
  const groups = raw.filter(g => g && g.group && g.group !== '#' && g.count > 0);
  const hash = raw.find(g => g && g.group === '#');
  if (!groups.length && !hash) return '';
  const list = groups.concat(hash ? [hash] : []);
  return '<div class="frow"><span class="lbl" style="margin:0">' + L.t('首字母') + '</span><div class="chips">' +
    '<span class="chip' + (!B.letter ? ' on' : '') + "\" data-bletter=\"\">" + L.t("全部") + '</span>' +
    list.map(g => '<span class="chip' + (B.letter === g.group ? ' on' : '') + '" data-bletter="' + esc(g.group) + '">' + esc(g.group) +
      '<span class="mini" style="opacity:.55;margin-left:4px">' + g.count + '</span></span>').join('') + '</div></div>';
}
function currentLibId() {
  const parts = String(S.route || '').split('/');
  return parts[1] === 'browse' && parts[2] ? parts[2] : '';
}

function libFilterHtml(B, mode) {
  const fc = browseFacets(currentLibId());
  const srcNames = (fc.onlinePublishers || []).map(x => x.value);
  const curLib = currentLibId() ? lib(currentLibId()) : null;
  const row = (label, chips) => '<div class="frow"><span class="lbl" style="margin:0">' + label + '</span><div class="chips">' + chips + '</div></div>';
  const fmt = fchip('bfmt', 'fmt', 'all', L.t('全部'), B) + ['cbx', 'epub', 'pdf', 'txt'].map(x => fchip('bfmt', 'fmt', x, SCAN_CN[x], B)).join('');
  const state = fchip('bstate', 'sstate', 'all', L.t('全部'), B) + ['ONGOING', 'ENDED', 'HIATUS', 'ABANDONED'].map(x => fchip('bstate', 'sstate', x, statusLabel(x), B)).join('');
  const regionCodes = fc.regions.map(x => x.value);
  const regionRow = row(L.t('地区'), fchip('bregion', 'region', 'all', L.t('全部'), B) + regionCodes.map(c => fchip('bregion', 'region', c, regionCn(c), B)).join('') + fchip('bregion', 'region', '__none', L.t('未知'), B));
  const scrapeRow = row(L.t('刮削'), ['all', 'done', 'none', 'bad'].map(k => fchip('bscrape', 'scrape', k, k === 'all' ? L.t('全部') : SCRAPE_STATE_CN[k], B)).join(''));
  const yearRow = row(L.t('年份'), fchip('byear', 'year', 'all', L.t('全部'), B) + (fc.years.length ? fc.years.map(y => fchip('byear', 'year', y.value, y.value, B)).join('') : '<span class="mini" style="align-self:center">' + L.t('刮削后可用') + '</span>'));
  const genreRow = row(L.t('meta.genres'), fchip('bgenre', 'genre', 'all', L.t('全部'), B) + (fc.genres.length ? fc.genres.slice(0, 12).map(g => fchip('bgenre', 'genre', g.value, g.value, B)).join('') : '<span class="mini" style="align-self:center">' + L.t('刮削后可用') + '</span>'));
  return (srcNames.length && (!curLib || curLib.type === 'ONLINE')
    ? row(L.t('在线源'),
      '<span class="chip' + (B.src === 'all' ? ' on' : '') + "\" data-libsrc=\"all\">" + L.t("全部（") + srcNames.length + L.t('）') + '</span>' +
      srcNames.map(x => '<span class="chip' + (B.src === x ? ' on' : '') + '" data-libsrc="' + esc(x) + '">' + esc(x) + '</span>').join(''))
    : '') +
    '<div class="frow"><span class="lbl" style="margin:0">' + L.t('格式') + '</span><div class="chips">' + fmt + '</div><span class="sep"></span><span class="lbl" style="margin:0">' + L.t('连载') + '</span><div class="chips">' + state + '</div></div>' +
    (regionCodes.length ? regionRow : '') +
    scrapeRow +
    (fc.years.length ? yearRow : '') +
    (fc.genres.length ? genreRow : '');
}
function libFilterPanelHtml(B, mode, extra) {
  return '<div class="filters fpanel">' + modeBarHtml(B) + libLetterBarHtml(B, mode) + libFilterHtml(B, mode) + libSortBarHtml(B, mode, extra) + '</div>';
}
function libSortBarHtml(B, mode, extra) {
  const sorts = mode === 'books'
    ? [['updated', L.t('按更新')], ['title', L.t('按标题')], ['series', L.t('按系列')]]
    : [['updated', L.t('按更新')], ['title', L.t('按标题')], ['count', L.t('按册数')]];
  return '<div class="frow">' +
    '<span class="lbl" style="margin:0">' + L.t('排序') + '</span><div class="chips">' +
    sorts.map(x => '<span class="chip' + ((B.sort || 'updated') === x[0] ? ' on' : '') + '" data-bsort="' + x[0] + '">' + x[1] + '</span>').join('') + '</div>' +
    '<span class="sep"></span><div class="chips">' + (extra || '') + '</div>' +
    '<input class="inp" style="width:190px;height:31px;margin-left:auto" placeholder="' + (mode === 'books' ? L.t('搜索书名或系列…') : L.t('搜索标题或作者…')) + '" value="' + esc(B.q) + '" data-q>' +
    '<div class="seg"><button class="' + (B.view === 'grid' ? 'on' : '') + '" data-view="grid">' + ico('grid') + '</button><button class="' + (B.view === 'list' ? 'on' : '') + '" data-view="list">' + ico('list') + '</button></div>' +
    '</div>';
}
function wireLibFilters(v, B) {
  v.querySelectorAll('[data-bfmt]').forEach(el => el.onclick = () => { B.fmt = el.dataset.bfmt; B.pg = 1; render(); });
  v.querySelectorAll('[data-bstate]').forEach(el => el.onclick = () => { B.sstate = el.dataset.bstate; B.pg = 1; render(); });
  v.querySelectorAll('[data-byear]').forEach(el => el.onclick = () => { B.year = el.dataset.byear; B.pg = 1; render(); });
  v.querySelectorAll('[data-bgenre]').forEach(el => el.onclick = () => { B.genre = el.dataset.bgenre; B.pg = 1; render(); });
  v.querySelectorAll('[data-bregion]').forEach(el => el.onclick = () => { B.region = el.dataset.bregion; B.pg = 1; render(); });
  v.querySelectorAll('[data-bscrape]').forEach(el => el.onclick = () => { B.scrape = el.dataset.bscrape; B.pg = 1; render(); });
  v.querySelectorAll('[data-bletter]').forEach(el => el.onclick = () => {
    B.letter = el.dataset.bletter || '';
    B.pg = 1;
    if (B.mode !== 'books') groupCache.key = '';
    render();
  });
  v.querySelectorAll('[data-bsort]').forEach(el => el.onclick = () => { B.sort = el.dataset.bsort; B.pg = 1; render(); });
}
function bookCard(b, pickSel) {
  const s = seriesOf(b), p = prog(b.id), pct = p && p.pages ? Math.round(p.page / p.pages * 100) : 0;
  const online = isOnlineBook(b);
  const t = online && s.t ? s.t : bookTitle(b), n = online ? '' : bookNumCn(b);
  const sub = online ? L.t('在线 · ') + num(s.chapters || 0) + L.t(' 话') : (s.t || '—');
  const box = (pickSel === undefined || pickSel === null) ? ''
    : '<span class="pkbox' + (pickSel ? ' on' : '') + '" data-pick-b="' + b.id + "\" title=\"" + L.t("选择") + "\">" + (pickSel ? '✓' : '') + '</span>';
  return '<div class="cv pk-wrap" data-book="' + b.id + '">' + box +
    coverArt((s.t || '') + t, t, { id: b.id, kind: 'book', fmt: b.profile, vert: false, badge: isOnlineBook(b) ? '<span class="badge gold">' + L.t('在线') + '</span>' : (n ? '<span class="st-badge">' + n + '</span>' : '') }) +
    '<div class="cv-meta"><div class="t">' + esc(t) + '</div>' +
    '<div class="s"><span>' + esc(sub) + '</span>' +
    (online ? '' : '<span style="margin-left:auto">' + bytes(b.size) + '</span>') + '</div>' +
    (p ? '<div class="pbar"><i class="' + (p.completed ? 'done' : '') + '" style="width:' + pct + '%"></i></div>' : '') + '</div></div>';
}
function renderBooksPage(v, l) {
  const B = S.browse;
  loadGroups(B);
  if (B.fmt !== 'all' && ['cbx', 'epub', 'pdf', 'txt'].indexOf(B.fmt) < 0) B.fmt = FMT_GROUP(B.fmt) || 'all';
  const data = booksData(B, l ? l.id : '');
  const fc = browseFacets(l ? l.id : '');
  const srcNames = (fc.onlinePublishers || []).map(x => x.value);
  if (B.src !== 'all' && srcNames.indexOf(B.src) < 0) B.src = 'all';
  if (B.genre !== 'all' && !fc.genres.some(x => x.value === B.genre)) B.genre = 'all';
  if (B.year !== 'all' && !fc.years.some(x => x.value === B.year)) B.year = 'all';
  if (B.region !== 'all' && B.region !== '__none' && !fc.regions.some(x => x.value === B.region)) B.region = 'all';
  if (B.sstate !== 'all' && !fc.statuses.some(x => x.value === B.sstate)) B.sstate = 'all';
  const list = data.rows;
  const pageList = list;
  const sizeAll = list.reduce((a, b) => a + b.size, 0);
  const letterNote = '';
  const head = l
    ? '<div class="crumb"><a data-go="/browse">' + L.t('书库') + '</a><i>/</i><b>' + esc(l.name) + '</b></div>' +
      '<div class="ph"><div><h1>' + esc(l.name) + ' <span class="badge ' + (l.type === 'ONLINE' ? 'gold' : 'moss') + '">' + (TYPE_CN[l.type] || l.type) + '</span></h1>' +
      '<div class="sub mono">' + esc(l.root) + ' · ' + (INTERVAL_CN[l.interval] || l.interval) + L.t('扫描 · ') + num(data.total || 0) + L.t(' 册') + '</div></div>' +
      '<div class="acts">' + (l.type === 'ONLINE'
        ? '<span class="badge warn">' + ico('shield') + L.t(' 受管库 · 扫描入口已隐藏') + '</span>' + (onlineReady() ? '<button class="btn" data-go="/online">' + ico('globe') + L.t('在线源入口') + '</button>' : '')
        : '<button class="btn" data-act="scanlib" data-id="' + l.id + '">' + ico('sync') + L.t('扫描库') + '</button><button class="btn" data-editlib="' + l.id + '">' + ico('edit') + L.t('编辑') + '</button>') +
      '<button class="btn pri" data-act="addbook">' + ico('plus') + L.t('导入书籍') + '</button></div></div>'
    : '<div class="ph"><div><h1>' + L.t('书库') + '</h1><div class="sub">' + L.t('全部 ') + num(data.total || 0) + L.t(' 册') + '</div></div>' +
      '<div class="acts"><button class="btn pri" data-go="/scrape">' + ico('wand') + L.t('刮削与元数据') + '</button><button class="btn" data-go="/libraries">' + ico('settings') + L.t('书库设置') + '</button></div></div>';

  const sel = B.sel || (B.sel = {});
  const picked = Object.keys(sel).filter(id => book(id));
  const allPicked = pageList.length > 0 && pageList.every(b => sel[b.id]);

  v.innerHTML = head + libFilterPanelHtml(B, 'books', pickChipsHtml(B, allPicked, picked.length));

  if (data.loading) {
    v.insertAdjacentHTML('beforeend', data.err ? loadErrorBlock(data.err, 'books') : loadingBlock(L.t('加载中…')));
  } else if (data.err && !pageList.length) {
    v.insertAdjacentHTML('beforeend', loadErrorBlock(data.err, 'books'));
  } else if (!pageList.length) {
    const msg = (B.letter || B.fmt !== 'all' || B.sstate !== 'all' || B.year !== 'all' || B.genre !== 'all' || B.src !== 'all' || B.q)
      ? '<div class="empty"><svg><use href="#i-book"/></svg><h4>' + L.t('没有符合条件的书籍') + '</h4><p>' + L.t('换一个筛选条件，或切回按系列。') + '</p></div>'
      : '<div class="empty"><svg><use href="#i-book"/></svg><h4>' + L.t('还没有书籍') + '</h4><p>' + L.t('导入或扫描书库后这里会出现全部书籍。') + '</p></div>';
    v.insertAdjacentHTML('beforeend', msg);
  } else if (B.view === 'grid') {
    const ck = chunkList(pageList, b => bookCard(b, B.pick ? !!sel[b.id] : null));
    v.insertAdjacentHTML('beforeend', '<div class="shelf" data-chunk>' + ck.head + '</div>');
    mountChunked(v, ck);
  } else {
    const ck = chunkList(pageList, b => bookRow(b, B.pick ? !!sel[b.id] : null));
    v.insertAdjacentHTML('beforeend', '<div class="tbl-wrap"><table class="tbl"><thead><tr>' + (B.pick ? '<th></th>' : '') + '<th></th><th>' + L.t('书名') + '</th><th>' + L.t('状态') + '</th><th>' + L.t('进度') + '</th><th class="num">' + L.t('更新') + '</th><th></th></tr></thead><tbody data-chunk>' + ck.head + '</tbody></table></div>');
    mountChunked(v, ck);
  }
  v.setAttribute('data-total', String(data.total || 0));
  v.insertAdjacentHTML('beforeend', pagerHtml(B, data.total || 0));
  wirePager(v, B);

  if (B.pick && picked.length) v.insertAdjacentHTML('beforeend', bulkBarHtml(picked.length, 'books'));

  wire(v);
  wireLibFilters(v, B);
  wireModeChips(v);

  const bm = v.querySelector('[data-bulk-mode]');
  if (bm) bm.onclick = () => { B.pick = !B.pick; if (!B.pick) B.sel = {}; render(); };
  v.querySelectorAll('[data-bulk]').forEach(el => el.onclick = () => bulkAction(el.dataset.bulk, 'books'));
  v.querySelectorAll('[data-pick-b]').forEach(el => el.onclick = e => {
    e.stopPropagation();
    const id = el.dataset.pickB;
    if (B.sel[id]) delete B.sel[id]; else B.sel[id] = 1;
    render();
  });
  const allBtn = v.querySelector('[data-bulk-all]');
  if (allBtn) allBtn.onclick = () => { pageList.forEach(b => { if (allPicked) delete B.sel[b.id]; else B.sel[b.id] = 1; }); render(); };
  const clr = v.querySelector('[data-bulk-clear]');
  if (clr) clr.onclick = () => { B.sel = {}; render(); };
}
