const THUMB_TYPE_CN = { GENERATED: L.t('自动生成'), SIDECAR: L.t('同名图片'), USER_UPLOADED: L.t('手动上传') };
function coverModal(kind, id, title) {
  if (!window.LantaiRuntime) return toast(L.t('后端不可用'), 'err');
  const path = 'api/v1/' + kind + '/' + id;
  LantaiRuntime.request(path + '/thumbnails').then(list => {
    const rows = (Array.isArray(list) ? list : []);
    openModal({
      title: title || L.t('封面管理'), width: 560,
      body: (rows.length
        ? rows.map(t => '<div class="list-i"><div style="width:52px;height:72px;flex:none;border-radius:4px;overflow:hidden;background:var(--line)">' +
          '<img src="' + path + '/thumbnails/' + t.id + '" alt="" style="width:100%;height:100%;object-fit:cover">' + '</div>' +
          '<div style="flex:1;min-width:0"><div class="gt">' + esc(THUMB_TYPE_CN[t.type] || t.type) + (t.selected ? ' <span class="badge ok">' + L.t('当前') + '</span>' : '') + '</div>' +
          '<div class="gs mono" style="font-size:10.5px">' + esc(t.width + '×' + t.height) + '</div></div>' +
          '<div class="gr">' + (t.selected ? '' : '<button class="btn xs" data-tsel="' + t.id + "\">" + L.t("设为封面") + '</button>') +
          (t.type === 'USER_UPLOADED' ? '<button class="btn xs danger" data-tdel="' + t.id + "\">" + L.t("删除") + '</button>' : '') + '</div></div>').join('')
        : '<div class="mini">' + L.t('还没有封面，上传一张试试。') + '</div>') +
      '<div class="note" style="margin-top:12px">' + L.t('自动生成的封面会随扫描重建；手动上传的封面可随时删除。') + '</div>',
      foot: '<button class="btn" data-x>' + L.t('关闭') + '</button><button class="btn pri" data-up>' + L.t('上传封面') + '</button>',
      after() {
        $('#modal [data-x]').onclick = closeModal;
        $('#modal [data-up]').onclick = () => {
          const inp = document.createElement('input');
          inp.type = 'file'; inp.accept = 'image/*';
          inp.onchange = () => {
            if (!inp.files || !inp.files[0]) return;
            const fd = new FormData();
            fd.append('file', inp.files[0]);
            fd.append('selected', 'true');
            fetch(path + '/thumbnails', { method: 'POST', credentials: 'same-origin', body: fd })
              .then(r => r.ok ? r.json() : Promise.reject(new Error('HTTP ' + r.status)))
              .then(() => { closeModal(); toast(L.t('封面已上传'), 'ok'); return LantaiRuntime.hydrate(); })
              .then(() => render())
              .catch(e => toast(L.t('上传失败：') + e.message, 'err'));
          };
          inp.click();
        };
        $$('#modal [data-tsel]').forEach(el => el.onclick = () => {
          LantaiRuntime.request(path + '/thumbnails/' + el.dataset.tsel + '/selected', { method: 'PUT' })
            .then(() => { closeModal(); toast(L.t('已设为封面'), 'ok'); render(); })
            .catch(e => toast(L.t('设置失败：') + onlineErrText(e), 'err'));
        });
        $$('#modal [data-tdel]').forEach(el => el.onclick = () => {
          LantaiRuntime.request(path + '/thumbnails/' + el.dataset.tdel, { method: 'DELETE' })
            .then(() => { closeModal(); toast(L.t('封面已删除'), 'ok'); render(); })
            .catch(e => toast(L.t('删除失败：') + onlineErrText(e), 'err'));
        });
      }
    });
  }).catch(e => toast(L.t('封面读取失败：') + onlineErrText(e), 'err'));
}

function coverLightbox(kind, id, title) {
  if (!window.LantaiRuntime || !id) return toast(L.t('后端不可用'), 'err');
  const seg = kind === 'series' ? 'series' : 'books';
  const path = 'api/v1/' + seg + '/' + id;
  const stamp = Date.now();
  const thumb = path + '/thumbnail?t=' + stamp;
  const full = path + '/thumbnail/original?t=' + stamp;
  openModal({
    title: title || L.t('封面'),
    width: 1120,
    body:
      '<div id="covStage" style="position:relative;background:var(--bg-2);border-radius:8px;height:74vh;overflow:hidden;display:flex;align-items:center;justify-content:center;cursor:grab;touch-action:none">' +
      '<img id="covImg" src="' + thumb + '" alt="" style="max-width:100%;max-height:100%;object-fit:contain;transform-origin:center center;user-select:none;-webkit-user-drag:none">' +
      '<div class="mini" style="position:absolute;right:10px;bottom:8px;color:var(--tx-3);pointer-events:none">' + L.t('滚轮缩放 · 拖动平移 · 双击复位') + '</div>' +
      '<div class="mini" id="covLoad" style="position:absolute;left:10px;bottom:8px;color:var(--tx-3);pointer-events:none">' + L.t('正在载入原图…') + '</div>' +
      '</div>' +
      '<div class="note" style="margin-top:10px">' + L.t('先显示缩略图，原图就位后自动替换成原始分辨率。替换封面只写库内封面（USER_UPLOADED），不改动原始文件；自动封面会随扫描重建。') + '</div>',
    foot: '<button class="btn" data-x>' + L.t('关闭') + '</button>' +
      '<button class="btn" data-save>' + ico('dl') + L.t('保存原图') + '</button>' +
      '<button class="btn" data-rep>' + ico('upload') + L.t('替换封面') + '</button>' +
      '<button class="btn ghost" data-manage>' + ico('layers') + L.t('封面管理') + '</button>',
    after() {
      const stage = $('#covStage');
      const img = $('#covImg');
      const tip = $('#covLoad');
      let zoom = 1, panX = 0, panY = 0, dragging = false, sx = 0, sy = 0, ox = 0, oy = 0;
      const apply = () => {
        img.style.transform = 'translate(' + panX + 'px,' + panY + 'px) scale(' + zoom + ')';
      };
      const reset = () => {
        zoom = 1;
        panX = 0;
        panY = 0;
        apply();
      };
      if (typeof Image !== 'undefined') {
        const probe = new Image();
        probe.onload = () => {
          img.src = probe.src;
          if (tip) tip.textContent = L.t('原图');
        };
        probe.onerror = () => {
          if (tip) tip.textContent = L.t('原始文件不可用，显示缩略图');
        };
        probe.src = full;
      }
      if (stage) {
        stage.onwheel = e => {
          e.preventDefault();
          const next = Math.min(8, Math.max(1, zoom * (e.deltaY < 0 ? 1.18 : 0.85)));
          if (next === zoom) return;
          zoom = next;
          if (zoom === 1) {
            panX = 0;
            panY = 0;
          }
          apply();
        };
        stage.onmousedown = e => {
          if (zoom <= 1) return;
          dragging = true;
          sx = e.clientX;
          sy = e.clientY;
          ox = panX;
          oy = panY;
          stage.style.cursor = 'grabbing';
        };
        stage.onmousemove = e => {
          if (!dragging) return;
          panX = ox + (e.clientX - sx);
          panY = oy + (e.clientY - sy);
          apply();
        };
        const stop = () => {
          dragging = false;
          stage.style.cursor = zoom > 1 ? 'grab' : 'default';
        };
        stage.onmouseup = stop;
        stage.onmouseleave = stop;
        stage.ondblclick = () => {
          if (zoom > 1) {
            reset();
          } else {
            zoom = 2;
            apply();
          }
        };
      }
      $('#modal [data-x]').onclick = closeModal;
      $('#modal [data-save]').onclick = () => {
        const a = document.createElement('a');
        a.href = full;
        a.download = String(title || kind) + '.jpg';
        document.body.appendChild(a);
        a.click();
        a.remove();
        toast(L.t('已开始下载原图'), 'ok');
      };
      $('#modal [data-rep]').onclick = () => {
        const inp = document.createElement('input');
        inp.type = 'file';
        inp.accept = 'image/*';
        inp.onchange = () => {
          if (!inp.files || !inp.files[0]) return;
          const fd = new FormData();
          fd.append('file', inp.files[0]);
          fd.append('selected', 'true');
          fetch(path + '/thumbnails', { method: 'POST', credentials: 'same-origin', body: fd })
            .then(r => r.ok ? r.json() : r.text().then(t => Promise.reject(new Error(t || ('HTTP ' + r.status)))))
            .then(() => {
              closeModal();
              toast(L.t('封面已替换'), 'ok');
              return LantaiRuntime.hydrate();
            })
            .then(() => render())
            .catch(e => toast(L.t('替换失败：') + onlineErrText(e), 'err'));
        };
        inp.click();
      };
      $('#modal [data-manage]').onclick = () => { closeModal(); coverModal(kind, id, title); };
    }
  });
}

