const RPRE = { font: 'Original', size: 100, line: 1.75, margin: 30, cols: 1, theme: 'default', layout: 'paged', continuous: false, fit: 'width', zoom: 100, twoPage: false };
try { Object.assign(RPRE, JSON.parse(localStorage.getItem('lantai-reader') || '{}')); } catch (e) { }
