    title: L.t('暂不支持在线阅读'), width: 460,
    body: '<div class="note">' + L.t('《') + name + L.t('》') + (fmt ? L.t('是 ') + esc(fmt) + L.t(' 格式，') : '') + L.t('当前只能下载原文件。') + '</div>' +
      '<div class="mini" style="margin-top:10px">' + L.t('安装转换器后可直接在线阅读。') + '</div>',
