    '<img src="api/lantai/v1/online/manga/' + m.mangaId + '/thumbnail' + (m.sourceId ? '?sourceId=' + encodeURIComponent(m.sourceId) : '') + '" alt="" loading="lazy" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:3" onerror="lantaiThumbRetry(this)"></div>';
