function onlineFilterHtml(src) {
  const list = (onlineFilterCache[src] || []).filter(f => f.type !== 'HEADER' && f.type !== 'SEPARATOR');
  if (!list.length) return '';
  const st = (S.online.filters || {})[src] || {};
  const rows = list.map(f => {
    const pos = f.position, dv = f.defaultValue;
    if (f.type === 'SELECT' || f.type === 'SORT') {
      const def = f.type === 'SORT' ? (dv && dv.index !== undefined ? dv.index : 0) : (dv == null ? 0 : dv);
      const cur = st[pos] && (st[pos].selectState !== undefined || st[pos].sortIndex !== undefined)
        ? (st[pos].selectState !== undefined ? st[pos].selectState : st[pos].sortIndex) : def;
      return '<select class="inp" data-ofil="' + pos + '" data-oftype="' + f.type + '" style="height:30px;width:auto;min-width:104px">' +
        (f.values || []).map((v, vi) => '<option value="' + vi + '"' + (Number(cur) === vi ? ' selected' : '') + '>' + esc(v) + '</option>').join('') + '</select>';
    }
    if (f.type === 'CHECKBOX') {
      const on = st[pos] ? !!st[pos].checkBoxState : !!dv;
      return '<label class="chip' + (on ? ' on' : '') + '"><input type="checkbox" data-ofil="' + pos + '" data-oftype="CHECKBOX" style="display:none"' + (on ? ' checked' : '') + '>' + esc(f.name) + '</label>';
    }
    if (f.type === 'TRISTATE') {
      const cur = st[pos] && st[pos].triState ? st[pos].triState : (typeof dv === 'string' ? dv : 'IGNORE');
      return '<select class="inp" data-ofil="' + pos + '" data-oftype="TRISTATE" style="height:30px;width:auto;min-width:110px">' +
        [['IGNORE', L.t('不限')], ['INCLUDE', L.t('包含')], ['EXCLUDE', L.t('排除')]].map(x => '<option value="' + x[0] + '"' + (cur === x[0] ? ' selected' : '') + '>' + esc(f.name) + ' · ' + x[1] + '</option>').join('') + '</select>';
    }
    if (f.type === 'TEXT') {
      const cur = st[pos] && st[pos].textState !== undefined ? st[pos].textState : (dv || '');
      return '<input class="inp" data-ofil="' + pos + '" data-oftype="TEXT" placeholder="' + esc(f.name) + '" value="' + esc(cur) + '" style="height:30px;width:132px">';
    }
    return '';
  }).join('');
  if (!rows) return '';
  return '<div class="filters" style="margin-top:12px;border-top:1px solid var(--line-3);padding-top:12px">' +
    '<span class="lbl" style="margin:0">' + L.t('筛选') + '</span>' + rows +
    '<button class="btn sm ghost" data-ofclear style="margin-left:auto">' + ico('close') + L.t('清空') + '</button></div>';
}
