function onlineRunBrowse(append) {
  const res = $('#onlineRes'); if (!res) return;
  if (!window.LantaiRuntime) { res.innerHTML = '<div class="note red">' + ico('alert') + L.t(' 后端不可用，无法浏览在线源。') + '</div>'; return; }
  const src = S.online.browseSrc;
  const type = S.online.browseType || 'POPULAR';
  const q = (S.online.browseQ || '').trim();
  if (!src) { res.innerHTML = '<div class="empty"><h4>' + L.t('先选一个在线源') + '</h4></div>'; return; }
  if (type === 'SEARCH' && !q) {
    onlineResults = null; onlineKey = '';
    res.innerHTML = '<div class="empty"><svg><use href="#i-globe"/></svg><h4>' + L.t('输入关键词在这个源里搜索') + '</h4></div>';
    return;
  }
  const key = 'b|' + src + '|' + type + '|' + q;
  if (!append && onlineResults && onlineKey === key) return paintOnlineResults(q);
  onlineKey = key; onlineErr = '';
  const page = append ? (onlinePage || 1) + 1 : 1;
  if (!append) {
    onlinePage = 1; onlineHasNext = false;
    res.innerHTML = '<div class="empty"><div class="spinner" style="margin:0 auto 12px"></div><h4>' + L.t('正在读取源站…') + '</h4><p>' + L.t('首次打开某个源可能要等几秒') + '</p></div>';
  }
  const body = { sourceId: src, type: type, page: page };
  if (q) body.q = q;
  const picked = (S.online.filters || {})[src];
  if (picked) {
    const arr = Object.keys(picked).map(k => Object.assign({ position: +k }, picked[k]));
    if (arr.length) body.filters = arr;
  }
  LantaiRuntime.request('api/lantai/v1/online/browse', { method: 'POST', body: body })
    .then(p => {
      const items = mapOnlineList((p && p.items) || []);
      onlineResults = append ? (onlineResults || []).concat(items) : items;
      onlinePage = (p && p.page) || page;
      onlineHasNext = !!(p && p.hasNextPage);
    })
    .catch(e => { if (!append) onlineResults = []; onlineHasNext = false; onlineErr = L.t('读取失败：') + onlineErrText(e); })
    .then(() => { const box = $('#onlineRes'); if (box && onlineKey === key) paintOnlineResults(q); });
}
function manageOnlineSources() {
  const rows = SOURCES.map(s => '<div class="rowflex" style="gap:9px;padding:7px 0;align-items:center;border-bottom:1px solid var(--line)">' +
    '<label class="sw"><input type="checkbox" data-srcon="' + esc(s.id) + '"' + (s.enabled ? ' checked' : '') + '><i></i></label>' +
    '<span style="flex:1">' + esc(s.name) + '</span><span class="mini mono">' + esc(s.lang || '') + '</span></div>').join('');
  openModal({
    title: L.t('在线源启用'), width: 520,
    body: rows || '<div class="note">' + L.t('还没有可用在线源') + '</div>',
    foot: '<button class="btn pri" data-x>' + L.t('完成') + '</button>',
    after() {
      $('#modal [data-x]').onclick = () => { closeModal(); render(); };
      $$('#modal [data-srcon]').forEach(el => el.onchange = () => {
        const id = el.dataset.srcon, on = el.checked;
        LantaiRuntime.request('api/lantai/v1/online/sources/' + encodeURIComponent(id), { method: 'PUT', body: { enabled: on } })
          .then(list => {
            if (Array.isArray(list)) {
              SOURCES.length = 0;
              list.forEach(x => SOURCES.push({ id: x.id, name: x.name, lang: x.lang, enabled: !!x.enabled }));
            } else {
              const hit = SOURCES.find(x => x.id === id); if (hit) hit.enabled = on;
            }
            toast(on ? L.t('已启用 ') + id : L.t('已停用 ') + id, 'ok');
          })
          .catch(e => { el.checked = !on; toast(L.t('切换失败：') + onlineErrText(e), 'err'); });
      });
    }
  });
}
