let trashData = null, trashSettings = null, trashErr = '', trashBusy = false;
function loadTrash() {
  if (trashBusy || !window.LantaiRuntime) return;
  trashBusy = true;
  Promise.all([
    LantaiRuntime.request('api/lantai/v1/trash'),
    LantaiRuntime.request('api/lantai/v1/trash/settings').catch(() => null)
  ]).then(([list, settings]) => {
    trashData = list || { entries: [], totalBytes: 0, maxBytes: 0 };
    trashSettings = settings;
  }).catch(e => {
    trashData = { entries: [], totalBytes: 0, maxBytes: 0 };
    trashErr = e && e.status === 403 ? L.t('需要管理员权限才能查看回收站。') : L.t('回收站载入失败，请稍后重试。');
  }).then(() => { trashBusy = false; if (S.route === '/trash') render(); });
}
function trashAct(fn, msg) {
  return fn().then(() => { toast(msg, 'ok'); trashData = null; trashErr = ''; render(); })
    .catch(() => toast(L.t('操作失败'), 'err'));
}
let excludedData = null, excludedErr = '', excludedBusy = false;
function loadExcluded() {
  if (excludedBusy || !window.LantaiRuntime) return;
  excludedBusy = true;
  LantaiRuntime.request('api/lantai/v1/trash/excluded')
    .then(list => { excludedData = Array.isArray(list) ? list : []; excludedErr = ''; })
    .catch(e => { excludedData = []; excludedErr = e && e.status === 403 ? L.t('需要管理员权限才能查看。') : L.t('载入失败，请稍后重试。'); })
    .then(() => { excludedBusy = false; if (S.route === '/trash') render(); });
}
function exclName(x) { return x.name || x.title || x.id; }
function renderExcluded(v, head) {
  if (!excludedData) {
    if (!excludedErr) loadExcluded();
    v.innerHTML = head + '<div class="card"><div class="empty" style="padding:56px 0">' +
      (excludedErr ? '<div class="mini">' + esc(excludedErr) + '</div>' : '<div class="spinner" style="margin:0 auto 12px"></div><div class="mini">' + L.t('正在载入…') + '</div>') + '</div></div>';
    return;
  }
  v.innerHTML = head + '<div class="card">' +
    (excludedData.length ? excludedData.map(x =>
      '<div class="list-i"><span class="gi" style="color:var(--tx-3)">' + ico('folder') + '</span>' +
      '<div style="flex:1;min-width:0"><div class="gt">' + esc(exclName(x)) + '</div>' +
      '<div class="gs mono" style="font-size:10.5px">' + esc(x.libraryId || '') + L.t(' · 文件仍在磁盘上') + '</div></div>' +
      '<div class="gr"><button class="btn xs" data-inex="' + x.id + "\">" + L.t("找回") + '</button></div></div>').join('')
      : '<div class="empty"><svg><use href="#i-check"/></svg><h4>' + L.t('没有移出书库的系列') + '</h4><p>' + L.t('在系列页点「移出书库」后，条目会出现在这里，随时可以找回。') + '</p></div>') +
    '<div class="note' + (excludedErr ? ' red' : '') + '" style="margin-top:14px">' + esc(excludedErr || L.t('移出书库不会改动磁盘上的文件，找回后下次扫描会重新入库。')) + '</div></div>';
}

const INS_SIZE = 20;
let inspectData = { dup: null, dupTotal: 0, dupPage: 0, known: null, knownTotal: 0, knownPage: 0, unknown: null, unknownTotal: 0, unknownPage: 0, busy: false, err: '' };
function inspectRequest(part) {
  const page = inspectData[part + 'Page'] || 0;
  const url = part === 'dup'
    ? 'api/lantai/v1/inspect/duplicate-groups?page=' + page + '&size=' + INS_SIZE
    : 'api/v1/page-hashes' + (part === 'unknown' ? '/unknown' : '') + '?page=' + page + '&size=' + INS_SIZE;
  return LantaiRuntime.request(url).then(res => {
    if (part === 'dup') {
      inspectData.dup = (res && res.groups) || [];
      inspectData.dupTotal = (res && res.totalGroups) || 0;
    } else {
      const list = unwrapPage(res);
      inspectData[part] = list;
      inspectData[part + 'Total'] = res && typeof res.totalElements === 'number' ? res.totalElements : list.length;
    }
    inspectData.err = '';
  }, () => {
    if (part === 'dup') { inspectData.dup = []; inspectData.dupTotal = 0; }
    else { inspectData[part] = []; inspectData[part + 'Total'] = 0; }
    inspectData.err = L.t('查重数据加载失败，需要管理员权限');
  });
}
function loadInspect(force) {
  if (!window.LantaiRuntime || inspectData.busy) return;
  const parts = ['dup', 'known', 'unknown'].filter(p => force || inspectData[p] === null);
  if (!parts.length) return;
  inspectData.busy = true;
  Promise.all(parts.map(inspectRequest)).then(() => {
    inspectData.busy = false;
    if (S.route === '/inspect') render();
  });
}
function inspectGoto(part, page) {
  if (inspectData.busy) return;
  inspectData[part + 'Page'] = Math.max(0, page);
  inspectData.busy = true;
  inspectRequest(part).then(() => {
    inspectData.busy = false;
    if (S.route === '/inspect') render();
  });
}
function insPager(part, total, page, unit) {
  const pages = Math.max(1, Math.ceil(total / INS_SIZE));
  const cur = clamp((page || 0) + 1, 1, pages);
  return '<div class="rowflex" style="gap:8px;align-items:center;margin-top:12px">' +
    '<button class="btn sm" data-inspage="' + part + '" data-pg="' + (cur - 1) + '"' + (cur <= 1 || inspectData.busy ? ' disabled' : '') + '>' + L.t('page.prev') + '</button>' +
    '<button class="btn sm" data-inspage="' + part + '" data-pg="' + (cur + 1) + '"' + (cur >= pages || inspectData.busy ? ' disabled' : '') + '>' + L.t('page.next') + '</button>' +
    '<span class="mini">' + cur + ' / ' + pages + L.t(' 页 · 共 ') + num(total) + (unit || L.t(' 项')) + '</span></div>';
}

