    '<button class="btn sm" data-logolder' + (LOGS.hasOlder && !LOGS.busy ? '' : ' disabled') + ">" + L.t("较早") + '</button>' +
    '<button class="btn sm" data-lognewer' + (LOGS.stack.length && !LOGS.busy ? '' : ' disabled') + ">" + L.t("较新") + '</button>' +
    '<span class="mini">' + L.t('本页 ') + LOGS.entries.length + L.t(' 条 · 每页 ') + LOG_PAGE + '</span></div>';
